define('taoQtiItem/qtiCreator/widgets/interactions/textEntryInteraction/states/Question',['jquery', 'lodash', 'i18n', 'taoQtiItem/qtiCreator/widgets/states/factory', 'taoQtiItem/qtiCreator/widgets/interactions/states/Question', 'taoQtiItem/qtiCreator/widgets/helpers/formElement', 'taoQtiItem/qtiCommonRenderer/helpers/patternMask', 'taoQtiItem/qtiCreator/helper/wproofreaderTextEntryAuthoring', 'tpl!taoQtiItem/qtiCreator/tpl/forms/interactions/textEntry', 'services/features'], function ($, _, __, stateFactory, Question, formElement, patternMaskHelper, textEntryWsc, formTpl, features) {
  'use strict';

  var TextEntryInteractionStateQuestion = stateFactory.extend(Question);
  TextEntryInteractionStateQuestion.prototype.initForm = function () {
    var _widget = this.widget,
      $form = _widget.$form,
      $inputs,
      interaction = _widget.element,
      patternMask = interaction.attr('patternMask'),
      dataPatternmaskMessage = interaction.attr('data-patternmask-message'),
      maxChars = parseInt(patternMaskHelper.parsePattern(patternMask, 'chars'), 10);
    var constraints = {
      none: {
        label: __("None"),
        selected: true
      },
      maxLength: {
        label: __("Max Length"),
        selected: false
      },
      pattern: {
        label: __("Pattern"),
        selected: false
      }
    };
    var baseAvailable = features.isVisible('taoQtiItem/creator/interaction/textEntry/property/base');
    var constraintsAvailable = features.isVisible('taoQtiItem/creator/interaction/textEntry/property/constraints');
    var recommendationsAvailable = features.isVisible('taoQtiItem/creator/interaction/textEntry/property/recommendations');
    if (!isNaN(maxChars) && maxChars > 0) {
      constraints.none.selected = false;
      constraints.maxLength.selected = true;
    } else if (patternMask !== null && patternMask !== undefined && patternMask !== '') {
      constraints.none.selected = false;
      constraints.pattern.selected = true;
    } else if (dataPatternmaskMessage !== null && dataPatternmaskMessage !== undefined && dataPatternmaskMessage !== '') {
      constraints.none.selected = false;
      constraints.pattern.selected = true;
    }
    $form.html(formTpl({
      base: parseInt(interaction.attr('base')),
      baseAvailable,
      placeholderText: interaction.attr('placeholderText'),
      expectedLength: parseInt(interaction.attr('expectedLength')),
      constraints,
      constraintsAvailable,
      recommendationsAvailable,
      patternMask: patternMask,
      dataPatternmaskMessage: dataPatternmaskMessage,
      maxLength: maxChars
    }));
    formElement.initWidget($form);
    _.defer(function () {
      textEntryWsc.attachInScope($form);
    });
    $inputs = {
      maxLength: $form.find('[name="maxLength"]'),
      patternMask: $form.find('[name="patternMask"]'),
      dataPatternmaskMessage: $form.find('[name="dataPatternmaskMessage"]')
    };
    formElement.setChangeCallbacks($form, interaction, {
      base: formElement.getAttributeChangeCallback(),
      placeholderText: formElement.getAttributeChangeCallback(),
      expectedLength: function expectedLength(interaction, attrValue) {
        interaction.attr('expectedLength', isNaN(parseInt(attrValue, 10)) ? 0 : attrValue);
      },
      constraint: function constraint(interaction, attrValue) {
        $('.constraint', $form).hide('500');
        $('.constraint-' + attrValue, $form).show('1000');
        if (attrValue === "none") {
          $('input', $form).val('');
          interaction.attr('patternMask', null);
        }
      },
      patternMask: function patternMask(interaction, attrValue) {
        interaction.attr('patternMask', attrValue);
        $inputs.maxLength.val('');
      },
      dataPatternmaskMessage: function dataPatternmaskMessage(interaction, attrValue) {
        interaction.attr('data-patternmask-message', attrValue);
      },
      maxLength: function maxLength(interaction, attrValue) {
        var newValue = parseInt(attrValue, 10);
        if (!isNaN(newValue)) {
          interaction.attr('patternMask', patternMaskHelper.createMaxCharPattern(newValue));
        }
        $inputs.patternMask.val(interaction.attr('patternMask'));
      }
    });
  };
  return TextEntryInteractionStateQuestion;
});
