define('taoQtiItem/qtiCreator/helper/languages',['util/url', 'core/dataProvider/request', 'module'], function (urlUtil, request, module) {
  'use strict';

  var config = module.config();
  var languagesUrl = config && config.languagesUrl || urlUtil.route('index', 'Languages', 'tao');
  var headers = {
    'Accept-version': 'v2'
  };
  var languagesRequest = null;
  var useLegacyFormatting = languages => {
    return languages.reduce((memo, lang) => {
      memo[lang.code] = lang.label;
      return memo;
    }, {});
  };
  var useCKEFormatting = languages => {
    return languages.map(lang => {
      return "".concat(lang.code, ":").concat(lang.label, ":").concat(lang.orientation);
    });
  };
  var getList = () => {
    if (languagesRequest === null) {
      return languagesRequest = request(languagesUrl, null, null, headers).then(sortLanguages);
    } else {
      return languagesRequest;
    }
  };
  var sortLanguages = languages => {
    return languages.sort((a, b) => {
      var labelA = (a.label || '').toLowerCase();
      var labelB = (b.label || '').toLowerCase();
      return labelA.localeCompare(labelB);
    });
  };
  var isRTLbyLanguageCode = code => {
    return getList().then(languages => {
      var lang = languages.filter(lang => lang.code === code);
      return lang[0] && lang[0].orientation === 'rtl' || false;
    });
  };
  var getVerticalWritingModeByLang = code => {
    return getList().then(languages => {
      var lang = languages.filter(lang => lang.code === code);
      return lang[0] && lang[0].verticalWritingMode || null;
    });
  };
  return {
    useLegacyFormatting,
    useCKEFormatting,
    getList,
    sortLanguages,
    isRTLbyLanguageCode,
    getVerticalWritingModeByLang
  };
});
