define('taoQtiItem/qtiCreator/helper/windowPopup',['lodash', 'jquery', 'ui/component', 'ui/component/draggable', 'ui/component/resizable', 'ui/component/stackable', 'ui/component/windowed'], function (_, $, componentFactory, makeDraggable, makeResizable, makeStackable, makeWindowed) {
  'use strict';

  var defaultConfig = {
    draggable: true,
    resizable: true,
    resizableEdges: {
      top: true,
      right: true,
      bottom: true,
      left: true
    }
  };
  return function windowPopupFactory(specs, config) {
    var windowPopup;
    config = _.defaults(config || {}, defaultConfig);
    windowPopup = componentFactory(specs, config);
    if (config.draggable) {
      makeDraggable(windowPopup);
    }
    if (config.resizable) {
      makeResizable(windowPopup, {
        edges: config.resizableEdges
      });
    }
    makeStackable(windowPopup, {
      stackingScope: 'qti-creator'
    });
    makeWindowed(windowPopup);
    windowPopup.on('render', function () {
      var $component = this.getElement();
      $component.addClass('window-popup');
    });
    return windowPopup;
  };
});
