define('taoQtiItem/qtiCreator/widgets/interactions/graphicGapMatchInteraction/helpers/gapTextTileLayout',['jquery', 'i18n'], function ($, __) {
  'use strict';

  var GAP_TEXT_MAX_TILE_WIDTH = 150;
  var GAP_TEXT_MIN_TILE_WIDTH = 75;
  var GAP_TEXT_MIN_TILE_HEIGHT = 60;
  var GAP_TEXT_SIDE_BAY_TILE_SIZE = 60;
  var GAP_TEXT_TILE_PADDING = 16;
  var GAP_TEXT_MAX_CHARS = 350;
  var GAP_TEXT_FONT_SIZE = 14;
  var GAP_TEXT_LINE_HEIGHT = 1.25;
  function normalizeGapTextTileLabel(label) {
    var normalizedLabel = (label || '').trim();
    if (!normalizedLabel || normalizedLabel === __('New label')) {
      return '';
    }
    return normalizedLabel;
  }
  function getPlainLabelFromGapText(gapText) {
    if (!gapText || typeof gapText.body !== 'function') {
      return '';
    }
    return normalizeGapTextTileLabel($('<div/>').html(gapText.body() || '').text().trim());
  }
  function mountGapTextTileLabel($gapTextBox, label) {
    $gapTextBox.empty();
    var $wrap = $('<div class="gap-text-label-wrap"/>');
    var $textarea = $('<textarea class="gap-text-label"/>').attr('aria-label', __('Label')).attr('placeholder', __('Enter text')).attr('rows', 1).attr('maxlength', GAP_TEXT_MAX_CHARS).prop('readonly', true).val(normalizeGapTextTileLabel(label));
    $wrap.append($textarea);
    $gapTextBox.append($wrap);
  }
  function mountGapTextTileFromModel($gapTextBox, gapText) {
    mountGapTextTileLabel($gapTextBox, getPlainLabelFromGapText(gapText));
  }
  function measureSampleTextWidth(sampleText, $context) {
    var $probeHost = $context && $context.length ? $context : $('body');
    var $measure = $('<span/>').css({
      position: 'absolute',
      visibility: 'hidden',
      whiteSpace: 'pre',
      fontFamily: $probeHost.css('font-family'),
      fontSize: "".concat(GAP_TEXT_FONT_SIZE, "px"),
      lineHeight: GAP_TEXT_LINE_HEIGHT,
      fontWeight: $probeHost.css('font-weight'),
      fontStyle: $probeHost.css('font-style'),
      letterSpacing: $probeHost.css('letter-spacing')
    }).text(sampleText || ' ');
    $('body').append($measure);
    var measured = Math.ceil($measure.outerWidth());
    $measure.remove();
    return measured;
  }
  function getLongestLine(text) {
    return (text || '').split('\n').reduce(function (longest, line) {
      return line.length > longest.length ? line : longest;
    }, '');
  }
  function resolveTileWidth(text, hasHardLineBreak) {
    var contentWidth = measureSampleTextWidth(getLongestLine(text) || ' ', null) + GAP_TEXT_TILE_PADDING;
    var wraps = hasHardLineBreak || contentWidth > GAP_TEXT_MAX_TILE_WIDTH;
    if (wraps) {
      return GAP_TEXT_MAX_TILE_WIDTH;
    }
    return Math.min(GAP_TEXT_MAX_TILE_WIDTH, Math.max(GAP_TEXT_MIN_TILE_WIDTH, contentWidth));
  }
  function isQuestionAuthoringView($gapTextBox) {
    return $gapTextBox.closest('.widget-box.edit-question').length > 0;
  }
  function isGapTextTileExpanded($gapTextBox) {
    return isQuestionAuthoringView($gapTextBox);
  }
  function isSideChoicesBay($gapTextBox) {
    return $gapTextBox.closest('.qti-graphicGapMatchInteraction.qti-choices-left, .qti-graphicGapMatchInteraction.qti-choices-right').length > 0;
  }
  function shouldFitContentHeight($gapTextBox) {
    return isQuestionAuthoringView($gapTextBox);
  }
  function applyTileDimensions($gapTextBox, tileWidth, tileHeight, expanded) {
    var sideBay = isSideChoicesBay($gapTextBox);
    if (sideBay) {
      tileWidth = GAP_TEXT_SIDE_BAY_TILE_SIZE;
    }
    $gapTextBox[0].style.setProperty('width', "".concat(tileWidth, "px"), 'important');
    $gapTextBox[0].style.setProperty('min-width', "".concat(sideBay ? GAP_TEXT_SIDE_BAY_TILE_SIZE : GAP_TEXT_MIN_TILE_WIDTH, "px"), 'important');
    $gapTextBox[0].style.setProperty('max-width', "".concat(sideBay ? GAP_TEXT_SIDE_BAY_TILE_SIZE : GAP_TEXT_MAX_TILE_WIDTH, "px"), 'important');
    $gapTextBox[0].style.setProperty('height', "".concat(tileHeight, "px"), 'important');
    $gapTextBox[0].style.setProperty('min-height', "".concat(GAP_TEXT_MIN_TILE_HEIGHT, "px"), 'important');
    $gapTextBox[0].style.setProperty('max-height', expanded ? 'none' : "".concat(tileHeight, "px"), 'important');
    $gapTextBox[0].style.setProperty('flex-shrink', '0', 'important');
    $gapTextBox.attr('data-gap-text-tile-width', tileWidth);
    $gapTextBox.toggleClass('gap-text-tile-expanded', expanded);
  }
  function getGapTextLineHeightPx($textarea) {
    var textareaEl = $textarea[0];
    if (!textareaEl || !window.getComputedStyle) {
      return Math.ceil(GAP_TEXT_FONT_SIZE * GAP_TEXT_LINE_HEIGHT);
    }
    var styles = window.getComputedStyle(textareaEl);
    var lineHeight = parseFloat(styles.lineHeight);
    if (!Number.isNaN(lineHeight) && lineHeight > 0) {
      return Math.ceil(lineHeight);
    }
    var fontSize = parseFloat(styles.fontSize) || GAP_TEXT_FONT_SIZE;
    return Math.ceil(fontSize * GAP_TEXT_LINE_HEIGHT);
  }
  function measureTextareaContentHeight($textarea, textareaEl, contentWidthPx) {
    var lineHeightPx = getGapTextLineHeightPx($textarea);
    var previousHeight = textareaEl.style.height;
    var previousMinHeight = textareaEl.style.minHeight;
    var previousWidth = textareaEl.style.width;
    $textarea.css({
      width: contentWidthPx ? "".concat(contentWidthPx, "px") : '100%',
      height: '0',
      minHeight: '0',
      overflowY: 'hidden'
    });
    var measuredHeight = Math.max(lineHeightPx, textareaEl.scrollHeight);
    textareaEl.style.height = previousHeight;
    textareaEl.style.minHeight = previousMinHeight;
    textareaEl.style.width = previousWidth;
    return measuredHeight;
  }
  function normalizeGapTextValue(value) {
    return (value || '').replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  }
  function syncGapTextTileSize($gapTextBox) {
    if (!$gapTextBox || !$gapTextBox.length) {
      return;
    }
    var fitContentHeight = shouldFitContentHeight($gapTextBox);
    var sideBay = isSideChoicesBay($gapTextBox);
    var $textarea = $gapTextBox.find('.gap-text-label');
    var textareaEl = $textarea[0];
    var tileWidth;
    var tileHeight = GAP_TEXT_MIN_TILE_HEIGHT;
    var normalizedValue;
    var textareaHeight;
    if ($textarea.length && textareaEl) {
      normalizedValue = normalizeGapTextValue(textareaEl.value || '');
      tileWidth = sideBay ? GAP_TEXT_SIDE_BAY_TILE_SIZE : resolveTileWidth(normalizedValue, normalizedValue.indexOf('\n') !== -1);
      if (!sideBay) {
        $gapTextBox[0].style.setProperty('width', "".concat(tileWidth, "px"), 'important');
      }
      if (fitContentHeight) {
        var innerWidth = Math.max(1, tileWidth - GAP_TEXT_TILE_PADDING);
        textareaHeight = measureTextareaContentHeight($textarea, textareaEl, innerWidth);
        tileHeight = Math.max(GAP_TEXT_MIN_TILE_HEIGHT, textareaHeight + GAP_TEXT_TILE_PADDING);
      }
    } else {
      var plainText = $gapTextBox.text().trim();
      tileWidth = sideBay ? GAP_TEXT_SIDE_BAY_TILE_SIZE : resolveTileWidth(plainText, plainText.indexOf('\n') !== -1);
    }
    applyTileDimensions($gapTextBox, tileWidth, tileHeight, fitContentHeight);
    if (!fitContentHeight) {
      $gapTextBox.find('.gap-text-label').css({
        height: '',
        minHeight: '',
        maxHeight: ''
      });
    }
    if ($textarea.length && textareaEl) {
      if (fitContentHeight) {
        var lineHeightPx = getGapTextLineHeightPx($textarea);
        $textarea.css({
          width: '100%',
          height: "".concat(textareaHeight, "px"),
          minHeight: "".concat(lineHeightPx, "px"),
          maxHeight: 'none',
          overflowX: 'hidden',
          overflowY: 'hidden'
        });
      } else {
        $textarea.css({
          width: '100%',
          height: '100%',
          minHeight: '0',
          maxHeight: '100%',
          overflowX: 'hidden',
          overflowY: 'auto'
        });
      }
    }
  }
  function syncAllGapTextTilesInList($gapList) {
    $gapList.find('li.qti-gapText').each(function () {
      syncGapTextTileSize($(this));
    });
  }
  return {
    GAP_TEXT_MAX_TILE_WIDTH,
    GAP_TEXT_MIN_TILE_WIDTH,
    GAP_TEXT_MIN_TILE_HEIGHT,
    GAP_TEXT_TILE_PADDING,
    GAP_TEXT_MAX_CHARS,
    normalizeGapTextTileLabel,
    getPlainLabelFromGapText,
    mountGapTextTileLabel,
    mountGapTextTileFromModel,
    isGapTextTileExpanded,
    syncGapTextTileSize,
    syncAllGapTextTilesInList
  };
});
