define('taoQtiItem/qtiCreator/renderers/Img',['lodash', 'context', 'taoQtiItem/qtiCommonRenderer/renderers/Img', 'taoQtiItem/qtiCreator/widgets/static/img/Widget', 'taoQtiItem/qtiCreator/widgets/static/figure/Widget', 'taoQtiItem/qtiCreator/model/Figure', 'taoQtiItem/qtiCreator/helper/findParentElement', 'taoQtiItem/qtiCreator/helper/elementSupport'], function (_, context, Renderer, Widget, FigureWidget, FigureModel, findParentElement, elementSupportHelper) {
  'use strict';

  var CreatorImg = _.clone(Renderer);
  var DISABLE_FIGURE_WIDGET = context.featureFlags && context.featureFlags.FEATURE_FLAG_DISABLE_FIGURE_WIDGET;
  CreatorImg.render = function (img, options) {
    var $container = Renderer.getContainer(img);
    if ($container.parent('figure').length || !DISABLE_FIGURE_WIDGET && $container.parent('span').length && $container.parent('span').data('figure')) {
      if (!DISABLE_FIGURE_WIDGET && !$container.parent('figure').length && $container.siblings('figcaption').length) {
        $container.siblings('figcaption').remove();
      }
      return CreatorImg;
    }
    options = options || {};
    options.baseUrl = this.getOption('baseUrl');
    options.uri = this.getOption('uri');
    options.lang = this.getOption('lang');
    options.mediaManager = this.getOption('mediaManager');
    options.assetManager = this.getAssetManager();
    options.state = img.metaData.widget && img.metaData.widget.getCurrentState().name;
    if (!DISABLE_FIGURE_WIDGET && elementSupportHelper.isFigureSupportedInParent($container)) {
      var parent = findParentElement(img.rootElement, img.serial);
      var imgPlaceholder = img.placeholder();
      var currentBody = parent.body();
      var figure = new FigureModel();
      var figurePlaceholder = figure.placeholder();
      var newBody = currentBody.replace(imgPlaceholder, figurePlaceholder);
      parent.removeElement(img);
      parent.body(newBody);
      parent.setElement(figure);
      var figureRenderer = parent.getRenderer();
      if (figureRenderer) {
        figure.setRenderer(figureRenderer);
        figureRenderer.load(() => {
          $container.trigger('graphicInteraction.ready');
        }, ['figure']);
      }
      figure.setElement(img);
      var $wrap = $container.wrap("<span data-serial=\"".concat(figure.serial, "\">")).parent();
      FigureWidget.build(figure, $wrap, this.getOption('bodyElementOptionForm'), options);
    } else {
      Widget.build(img, Renderer.getContainer(img), this.getOption('bodyElementOptionForm'), options);
    }
  };
  return CreatorImg;
});
